// Package headers configures optional wire headers while preserving the
// identity, resource binding and message framing generated by the protocol.
package headers

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"os"
	"strings"
)

// DefaultUserAgent is a compatibility profile for the gateway transport.
// This string is protocol metadata and does not change device registration.
const DefaultUserAgent = "Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/54.0.2840.71 Safari/537.36 TPNClient/3.0.5.0"

type Profile struct {
	UserAgent string            `json:"user_agent,omitempty"`
	Control   map[string]string `json:"control_headers,omitempty"`
	Gateway   map[string]string `json:"gateway_headers,omitempty"`
}

func (p Profile) Agent() string {
	if p.UserAgent != "" {
		return p.UserAgent
	}
	return DefaultUserAgent
}

// Optional headers cannot replace cryptographic/session claims or introduce
// a second framing interpretation. In particular, CONNECT auth is never user
// supplied and cannot be copied to the resource's HTTP request.
func (p Profile) Validate() error {
	if len(p.Agent()) > 2048 || !printable(p.Agent()) {
		return errors.New("invalid User-Agent")
	}
	reserved := strings.Fields("host user-agent authorization proxy-authorization proxy-authenticate cookie set-cookie connection proxy-connection content-type content-length transfer-encoding upgrade trailer te tenant-id client-mid client-guid client-platform client-machine client-version content-encrypt content-seq proto-cmd proto-ver language timestamp mid version request-id requestid platform domain ts ts-offset nonce sign tnonce x-sga-pn x-sga-mn x-rio-seq x-forwarded-for server-ip source-addr protocol x-proxy-type")
	blocked := map[string]bool{}
	for _, name := range reserved {
		blocked[name] = true
	}
	total := len(p.Agent())
	for _, extra := range []map[string]string{p.Control, p.Gateway} {
		if len(extra) > 32 {
			return errors.New("too many custom headers")
		}
		seen := map[string]bool{}
		for name, value := range extra {
			lower := strings.ToLower(name)
			if name == "" || len(name) > 128 || blocked[lower] || seen[lower] {
				return errors.New("custom header is reserved, duplicated or invalid")
			}
			seen[lower] = true
			for _, c := range name {
				if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("!#$%&'*+-.^_`|~", c)) {
					return errors.New("invalid custom header name")
				}
			}
			if len(value) > 2048 || !printable(value) {
				return errors.New("invalid custom header value")
			}
			total += len(name) + len(value) + 4
		}
	}
	if total > 8192 {
		return errors.New("custom header profile exceeds 8 KiB")
	}
	return nil
}

func printable(s string) bool {
	for _, c := range s {
		if c < 32 || c > 126 {
			return false
		}
	}
	return true
}

func (p Profile) ApplyControl(req *http.Request) error {
	if err := p.Validate(); err != nil {
		return err
	}
	req.Header.Set("User-Agent", p.Agent())
	for k, v := range p.Control {
		req.Header.Set(k, v)
	}
	return nil
}

func Load(path string) (Profile, error) {
	var p Profile
	f, err := os.Open(path)
	if err != nil {
		return p, err
	}
	defer f.Close()
	info, err := f.Stat()
	if err != nil {
		return p, err
	}
	if !info.Mode().IsRegular() || info.Size() > 16384 {
		return p, errors.New("header profile must be a regular file smaller than 16 KiB")
	}
	dec := json.NewDecoder(io.LimitReader(f, 16385))
	dec.DisallowUnknownFields()
	if dec.Decode(&p) != nil || dec.Decode(new(any)) != io.EOF {
		return p, errors.New("invalid header profile JSON")
	}
	return p, p.Validate()
}
